do $$declare c public.vehicle_maintenance_cases;manager_u uuid;other_u uuid:='99000000-0000-0000-0000-000000000001';it_u uuid:='98000000-0000-0000-0000-000000000001';n bigint;escalation_id uuid;begin
 select*into c from public.vehicle_maintenance_cases where manager_id is not null order by reported_at desc limit 1;if c.id is null then raise exception'MAINTENANCE_FIXTURE_REQUIRED';end if;manager_u:=c.manager_id;
 insert into auth.users(id,email)values(other_u,'timeline-other@x.iq');
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',manager_u::text,false);
 select count(*)into n from public.maintenance_case_events(c.id)where event_type in('case','movement','maintenance_update');if n<2 then raise exception'MAINTENANCE_UNIFIED_TIMELINE_FAIL';end if;
 perform set_config('request.jwt.claim.sub',other_u::text,false);begin perform public.maintenance_case_events(c.id);raise exception'TIMELINE_ISOLATION_ACCEPTED';exception when others then if sqlerrm='TIMELINE_ISOLATION_ACCEPTED'then raise;end if;if sqlerrm not like'%MAINTENANCE_CASE_FORBIDDEN%'then raise;end if;end;
 execute'reset role';update public.vehicle_maintenance_cases set arrived_at=null,ready_at=null,readiness_approved_at=null,departed_maintenance_at=null,completed_at=null,status='in_repair'where id=c.id;update public.vehicle_maintenance_cases set arrived_at=now(),status='in_repair',progress=60 where id=c.id;update public.vehicle_trip_legs set arrived_at=coalesce(arrived_at,now()),arrived_by=coalesce(arrived_by,manager_u)where departure_id=c.departure_id and destination_type='maintenance';
 select count(*)into n from public.notifications where entity_id=c.id and dedupe_key like'maintenance_case:%:arrived:garage';if n<1 then raise exception'MAINTENANCE_ARRIVAL_GARAGE_NOTIFICATION_FAIL';end if;
 delete from public.notifications where entity_id=c.id and dedupe_key='maintenance_case:'||c.id::text||':escalation';
 insert into public.notification_push_subscriptions(user_id,endpoint,p256dh,auth_key,platform,device_name)values(it_u,'https://push.example.test/multi-a/1234567890',repeat('a',65),repeat('b',24),'android','Android متعدد'),(it_u,'https://push.example.test/multi-b/1234567890',repeat('c',65),repeat('d',24),'ios','iPhone متعدد');
 insert into public.notification_preferences(user_id,push_enabled)values(it_u,true)on conflict(user_id)do update set push_enabled=true;
 update public.notification_workflow_policies set escalation_minutes=1 where sector_id is null and vehicle_category is null;update public.vehicle_maintenance_cases set garage_decision_status='awaiting_ack',reported_at=now()-interval'2 minutes'where id=c.id;
 perform set_config('role','service_role',false);perform set_config('request.jwt.claims','{"role":"service_role"}',false);perform public.notification_evaluate_workflow_escalations();perform public.notification_evaluate_workflow_escalations();execute'reset role';
 select id into escalation_id from public.notifications where user_id=it_u and entity_id=c.id and dedupe_key='maintenance_case:'||c.id::text||':escalation';if escalation_id is null then raise exception'MULTI_DEVICE_ESCALATION_MISSING';end if;select count(*)into n from public.notification_push_deliveries where notification_id=escalation_id;if n<>2 then raise exception'MULTI_DEVICE_ESCALATION_FANOUT_FAIL';end if;select count(*)into n from public.notifications where user_id=it_u and entity_id=c.id and dedupe_key='maintenance_case:'||c.id::text||':escalation';if n<>1 then raise exception'MULTI_DEVICE_ESCALATION_DEDUPE_FAIL';end if;
 update public.vehicle_maintenance_cases set garage_decision_status='not_required',ready_at=coalesce(ready_at,now()),readiness_approved_at=coalesce(readiness_approved_at,now()),departed_maintenance_at=coalesce(departed_maintenance_at,now()),status='to_work',progress=100 where id=c.id;
 select count(*)into n from public.notifications where entity_id=c.id and dedupe_key like'maintenance_case:%:departed-to-work:garage';if n<1 then raise exception'MAINTENANCE_DEPARTURE_GARAGE_NOTIFICATION_FAIL';end if;
 update public.vehicle_maintenance_cases set completed_at=now(),status='returned_to_work'where id=c.id;
 select count(*)into n from public.notifications where entity_id=c.id and dedupe_key like'maintenance_case:%:returned-to-work:%';if n<1 then raise exception'MAINTENANCE_RETURN_NOTIFICATION_FAIL';end if;
 perform set_config('role','authenticated',false);perform set_config('request.jwt.claim.sub',manager_u::text,false);
 select count(*)into n from public.maintenance_case_events(c.id)where event_type='completion'and status='returned_to_work';if n<>1 then raise exception'MAINTENANCE_COMPLETION_EVENT_FAIL';end if;select count(*)into n from public.maintenance_case_events(c.id)where event_key like'leg:%:departed';if n<1 then raise exception'MAINTENANCE_DEPARTURE_EVENTS_MISSING';end if;select count(*)into n from public.maintenance_case_events(c.id)where event_key like'leg:%:arrived';if n<1 then raise exception'MAINTENANCE_ARRIVAL_EVENTS_MISSING';end if;
 perform set_config('request.jwt.claim.sub',it_u::text,false);select count(*)into n from public.notification_push_delivery_page(24,null,null,25,0);if n<1 then raise exception'PUSH_DELIVERY_PAGE_FAIL';end if;
 begin perform public.notification_push_delivery_page(0,null,null,25,0);raise exception'PUSH_FILTER_LIMIT_ACCEPTED';exception when others then if sqlerrm='PUSH_FILTER_LIMIT_ACCEPTED'then raise;end if;if sqlerrm not like'%PUSH_DELIVERY_FILTER_INVALID%'then raise;end if;end;
 perform set_config('request.jwt.claim.sub',other_u::text,false);begin perform public.notification_push_delivery_page(24,null,null,25,0);raise exception'PUSH_PAGE_ISOLATION_ACCEPTED';exception when others then if sqlerrm='PUSH_PAGE_ISOLATION_ACCEPTED'then raise;end if;if sqlerrm not like'%PUSH_OPERATIONS_FORBIDDEN%'then raise;end if;end;
 raise notice'✅ الجولة 15: تسلسل الصيانة/تنبيهات الوصول والعودة/عزل تفاصيل Push والحدود ناجحة';end$$;
